package com.taskflow.service; import com.taskflow.dto.AuthDtos.*; import com.taskflow.entity.*; import com.taskflow.exception.*; import com.taskflow.repository.*; import com.taskflow.security.*; import org.springframework.http.*; import org.springframework.security.crypto.password.*; import org.springframework.stereotype.*;
@Service public class AuthService{final UserRepository users;final PasswordEncoder enc;final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;}public AuthResponse register(RegisterRequest r){String email=r.email().toLowerCase();if(users.existsByEmail(email))throw new ApiException(HttpStatus.CONFLICT,"Email already registered");User u=new User();u.setName(r.name());u.setEmail(email);u.setPasswordHash(enc.encode(r.password()));users.save(u);return out(u);}public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!enc.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return out(u);}AuthResponse out(User u){return new AuthResponse(jwt.generate(u.getId(),u.getEmail()),u.getId(),u.getName(),u.getEmail());}}
